public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 0) {
        return result;
    }
    boolean[] used = new boolean[nums.length];
    List<Integer> list = new ArrayList<>();
    dfs(nums, used, list, result);
    return result;
}

private void dfs(int[] nums, boolean[] used, List<Integer> list, List<List<Integer>> result) {
    if (list.size() == nums.length) {
        result.add(new ArrayList<Integer>(list));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) {
            continue;
        }
        used[i] = true;
        list.add(nums[i]);
        dfs(nums, used, list, result);
        used[i] = false;
        list.remove(list.size() - 1);
    }
}

public List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> permutations = new LinkedList<>();
        if (nums == null || nums.length == 0) {
            return permutations;
        }
        permutations.add(Arrays.asList(nums));
        for (int i = 1; i < nums.length; i++) {
            List<List<Integer>> newPermutations = new LinkedList<>();
            for (List<Integer> permutation : permutations) {
                for (int j = 0; j < permutation.size(); j++) {
                    List<Integer> newPermutation = new ArrayList<>(permutation);
                    newPermutation.add(j, nums[i]);
                    newPermutations.add(newPermutation);
                }
            }
            permutations = newPermutations;
        }
        return permutations;
    }

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return permutations;
    }
    permute(nums, 0, permutations);
    return permutations;
}

private void permute(int[] nums, int start, List<List<Integer>> permutations) {
    if (start == nums.length) {
        permutations.add(new ArrayList<Integer>(nums.length));
        return;
    }
    for (int i = start; i < nums.length; i++) {
        swap(nums, start, i);
        permute(nums, start + 1, permutations);
        swap(nums, start, i);
    }
}

private void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
}

