        result.add(new ArrayList<>());
        return result;
    }
    for (int i = 0; i < nums.length; i++) {
        int current = nums[i];
        List<List<Integer>> recurseResult = permute(nums, i + 1);
        for (List<Integer> list : recurseResult) {
            list.add(0, current);
            result.add(list);
        }
    }
