private static void markConnected(char[][] grid, boolean[][] visited, int i, int j) {
    int m = grid.length;
    int n = grid[0].length;
    Deque<Integer> queue = new ArrayDeque<>();
    queue.addLast(i * n + j);
    while (!queue.isEmpty()) {
