        int x = pos / n;
        int y = pos % n;
        if (grid[x][y] == '@' && !visited[x][y]) {
            visited[x][y] = true;
            queue.addLast(x * n + y - 1);
            queue.addLast(x * n + y + 1);
            queue.addLast((x - 1) * n + y);
            queue.addLast((x + 1) * n + y);
        }
    }
}

