    if (currentStr.equals(posToString(end))) {
      return "can be travelled";
    }

    // Add all unvisited neighbors of the current n-tersection to the queue and visited set
    int[] currentPos = stringToPos(currentStr);
    for (int[] neighborPos : getNeighbors(currentPos, paths)) {
      String neighborStr = posToString(neighborPos);
      if (!visited.contains(neighborStr)) {
