}

private static String posToString(int[] pos) {
  return "" + pos[0] + "," + pos[1];
}

private static int[] stringToPos(String posStr) {
  String[] posArr = posStr.split(",");
  return new int[] {Integer.parseInt(posArr[0]), Integer.parseInt(posArr[1])};
}

private static int[][] getNeighbors(int[] pos, int[][] paths) {
  List<int[]> neighbors = new ArrayList<>();
  for (int[] path : paths) {
    if (path[0] == pos[0] || path[1] == pos[1]) {
      // If the path connects the current n-tersection, get the neighbor n-tersection
      int[] neighborPos = path[0] == pos[0] ? new int[] {pos[0], path[1]} : new int[] {path[0], pos[1]};
      neighbors.add(neighborPos);
    }
  }
  return neighbors.toArray(new int[neighbors.size()][]);
}

