public static String convertDatesToWeekdays(String date) {
    String[] dateParts = date.split(" ");
    int month = Integer.parseInt(dateParts[0]);
    int day = Integer.parseInt(dateParts[1]);
    int year = Integer.parseInt(dateParts[2]);
    Calendar calendar = Calendar.getInstance();
    calendar.set(year, month - 1, day);
    int weekday = calendar.get(Calendar.DAY_OF_WEEK);
    String weekdayName = getWeekdayName(weekday);
    return day + "." + month + "." + year + " is a " + weekdayName;
}

public static String getWeekdayName(int weekday) {
    switch (weekday) {
        case Calendar.SUNDAY:
            return "Sunday";
        case Calendar.MONDAY:
            return "Monday";
        case Calendar.TUESDAY:
            return "Tuesday";
        case Calendar.WEDNESDAY:
            return "Wednesday";
        case Calendar.THURSDAY:
            return "Thursday";
        case Calendar.FRIDAY:
            return "Friday";
        case Calendar.SATURDAY:
            return "Saturday";
        default:
            return "";
    }
}

public static String convertDatesToWeekdays(String date) {
    // Convert the input date to a Date object
    DateFormat df = new SimpleDateFormat("MM dd yyyy");
    Date dateObject;
    try {
        dateObject = df.parse(date);
    } catch (ParseException e) {
        return "Invalid input date";
    }

    // Get the weekday of the date
    Calendar calendar = Calendar.getInstance();
    calendar.setTime(dateObject);
    int dayOfWeek = calendar.get(Calendar.DAY_OF_WEEK);

    // Map the day of week to a weekday name
    String weekdayName;
    switch (dayOfWeek) {
        case Calendar.SUNDAY:
            weekdayName = "Sunday";
            break;
        case Calendar.MONDAY:
            weekdayName = "Monday";
            break;
        case Calendar.TUESDAY:
            weekdayName = "Tuesday";
            break;
        case Calendar.WEDNESDAY:
            weekdayName = "Wednesday";
            break;
        case Calendar.THURSDAY:
            weekdayName = "Thursday";
            break;
        case Calendar.FRIDAY:
            weekdayName = "Friday";
            break;
        case Calendar.SATURDAY:
            weekdayName = "Saturday";
            break;
        default:
            weekdayName = "Invalid weekday";
            break;
    }

    // Return the formatted date and weekday name
    return date + " is a " + weekdayName;
}

