public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a 2D array to store the minimum time required to collect all apples
    int[][] dp = new int[n][n];

    // Initialize the root node
    dp[0][0] = 0;

    // Iterate over each node
    for (int i = 1; i < n; i++) {
        // Iterate over each edge connected to the current node
        for (int j = 0; j < edges[i].length; j++) {
            // If the current node has an apple, add the time required to collect it
            if (hasApple[i]) {
                dp[i][j] += 1;
            }

            // Add the time required to move from the current node to the connected node
            dp[i][j] += dp[edges[i][j]][0];
        }
    }

    // Iterate over each edge connected to the root node
    for (int i = 0; i < edges[0].length; i++) {
        // Add the time required to move from the root node to the connected node
        dp[0][i] += dp[edges[0][i]][0];
    }

    // Return the minimum time required to collect all the apples and return to the root node
    return dp[0][n - 1];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a min priority queue to store the nodes and their distances
    PriorityQueue<int[]> queue = new PriorityQueue<>((a, b) -> a[0] - b[0]);

    // Add the starting node to the queue with distance 0
    queue.add(new int[]{0, 0, 0});

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the next node and its distance from the queue
        int[] node = queue.poll();
        int distance = node[0];
        int parent = node[1];

        // If the node has an apple, add its distance to the total distance
        if (hasApple[node[2]]) {
            distance += node[0];
        }

        // If the node is not the starting node, add its distance to the total distance
        if (parent != 0) {
            distance += node[0];
        }

        // Add all the child nodes to the queue with the total distance
        for (int i = 0; i < edges.length; i++) {
            int edge = edges[i][0];
            if (edge == node[2] && hasApple[i]) {
                int child = edges[i][1];
                queue.add(new int[]{distance, node[2], child});
            }
        }
    }

    // Return the total distance
    return distance;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a 2D array to store the min time required to collect all apples and return to node 0
    int[][] minTime = new int[n + 1][n + 1];

    // Initialize the 2D array with 0
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n; j++) {
            minTime[i][j] = 0;
        }
    }

    // Calculate the min time required to collect all apples and return to node 0
    for (int i = 1; i <= n; i++) {
        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            if (hasApple[v]) {
                minTime[i][u] = Math.min(minTime[i][u], minTime[v][v] + minTime[u][u]);
            }
        }
    }

    // Return the min time required to collect all apples and return to node 0
    return minTime[n][0];
}

