public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Initialize a 2D matrix to store the minimum time to reach each node
  // from node 0. Initialize all values to infinity.
  int[][] minTime = new int[n][n];
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      minTime[i][j] = Integer.MAX_VALUE;
    }
  }

  // Initialize the minimum time to reach node 0 to 0.
  minTime[0][0] = 0;

  // Traverse the tree and update the minimum time for each node.
  for (int i = 0; i < edges.length; i++) {
    int node1 = edges[i][0];
    int node2 = edges[i][1];
    minTime[node1][node2] = Math.min(minTime[node1][node2], minTime[node1][node1] + 1);
    minTime[node2][node1] = Math.min(minTime[node2][node1], minTime[node2][node2] + 1);
  }

  // Traverse the tree again and update the minimum time for each node
  // based on the values computed in the previous traversal.
  for (int i = 0; i < edges.length; i++) {
    int node1 = edges[i][0];
    int node2 = edges[i][1];
    for (int j = 0; j < n; j++) {
      if (minTime[j][node1] != Integer.MAX_VALUE && minTime[j][node2] != Integer.MAX_VALUE) {
        minTime[j][node1] += minTime[node2][node1];
        minTime[j][node2] += minTime[node2][node2];
      }
    }
  }

  // Compute the final result.
  int result = Integer.MAX_VALUE;
  for (int i = 0; i < n; i++) {
    if (hasApple[i]) {
      result = Math.min(result, minTime[0][i]);
    }
  }
  return result == Integer.MAX_VALUE ? 0 : result;
}

