public String sortString(String s) {
    // Initialize an empty result string
    String result = "";

    // Loop until all characters in s have been processed
    while (result.length() < s.length()) {
        // Find the smallest character in s that is not already in result
        char smallestChar = findSmallestChar(s, result);

        // Append the smallest character to result
        result += smallestChar;

        // Find the largest character in s that is not already in result
        char largestChar = findLargestChar(s, result);

        // Append the largest character to result
        result += largestChar;
    }

    return result;
}

private char findSmallestChar(String s, String result) {
    // Initialize the smallest character to the maximum value
    char smallestChar = Character.MAX_VALUE;

    // Loop through each character in s
    for (char c : s.toCharArray()) {
        // Check if the character is not already in result
        if (!result.contains(c)) {
            // Update the smallest character if necessary
            smallestChar = smallestChar > c ? c : smallestChar;
        }
    }

    return smallestChar;
}

private char findLargestChar(String s, String result) {
    // Initialize the largest character to the minimum value
    char largestChar = Character.MIN_VALUE;

    // Loop through each character in s
    for (char c : s.toCharArray()) {
        // Check if the character is not already in result
        if (!result.contains(c)) {
            // Update the largest character if necessary
            largestChar = largestChar < c ? c : largestChar;
        }
    }

    return largestChar;
}

