}

private char getNextChar(char[] chars, StringBuilder result) {
    char nextChar = chars[0];
    for (int i = 1; i < chars.length; i++) {
        char c = chars[i];
        if (c > nextChar && (result.length() == 0 || c <= result.charAt(result.length() - 1))) {
            nextChar = c;
        }
    }
    return nextChar;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    char[] charArray = s.toCharArray();

    // repeatedly pick the smallest and largest characters from the remaining characters and append them to the result
    while (result.length() < s.length()) {
        char smallestChar = findSmallest(charArray);
        result.append(smallestChar);
        replace(charArray, smallestChar, (char) 0);

        char largestChar = findLargest(charArray);
        result.append(largestChar);
        replace(charArray, largestChar, (char) 0);
    }

    return result.toString();
}

private char findSmallest(char[] charArray) {
    char smallest = Character.MAX_VALUE;
    for (char c : charArray) {
        if (c < smallest && c != (char) 0) {
            smallest = c;
        }
    }
    return smallest;
}

private char findLargest(char[] charArray) {
    char largest = Character.MIN_VALUE;
    for (char c : charArray) {
        if (c > largest && c != (char) 0) {
            largest = c;
        }
    }
    return largest;
}

private void replace(char[] charArray, char oldChar, char newChar) {
    for (int i = 0; i < charArray.length; i++) {
        if (charArray[i] == oldChar) {
            charArray[i] = newChar;
        }
    }
}

public static boolean splitArraySameAverage(int[] nums) {
