    for (int i = 0; i < cost.length; i++) {
        int currentCost = cost[i];
        if (i == 0 || i == 1) {
            continue;
        }
        int prevCost = cost[i - 1];
        int nextCost = cost[i - 2];
        currentCost = Math.min(prevCost + currentCost, nextCost + currentCost);
        minCost = Math.min(minCost, currentCost);
    }
    return minCost;
}

