public static boolean hasAllCodes(String s, int k) {
    int mask = (1 << k) - 1;
    int[] dp = new int[26];
    for (int i = 0; i < s.length(); i++) {
        int val = s.charAt(i) - '0';
        dp[i & mask] ^= val << 1;
        if ((dp[i & mask] & (1 << k) - 1) == 0) return true; // Found a substring of length k
    }
    return false;
}

