public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int[][] dp = new int[m][n];
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j] = 1;
                if (i > 0 && j > 0) {
                    dp[i][j] = Math.min(dp[i - 1][j], Math.min(dp[i][j - 1], dp[i - 1][j - 1])) + 1;
                } else if (i > 0) {
                    dp[i][j] = Math.min(dp[i - 1][j], dp[i][j - 1]) + 1;
                } else if (j > 0) {
                    dp[i][j] = Math.min(dp[i - 1][j], dp[i][j - 1]) + 1;
                }
            }
        }
    }

    int maxLength = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (dp[i][j] > maxLength) {
                maxLength = dp[i][j];
            }
        }
    }

    return maxLength;
}

public static int longestLine(int[][] mat) {
    int rows = mat.length;
    int cols = mat[0].length;
    int globalMax = 0;

    // Horizontal
    for(int i = 0; i < rows; i++) {
            int currentMax = 0;
            for(int j = 0; j < cols; j++) {
                    if(mat[i][j] == 1) {
                            currentMax++;
                            if(currentMax > globalMax) {
                                    globalMax = currentMax;
                            }
                    } else {
                            currentMax = 0;
                    }
            }
    }

    // Vertical
    for(int i = 0; i < cols; i++) {
            int currentMax = 0;
            for(int j = 0; j < rows; j++) {
                    if(mat[j][i] == 1) {
                            currentMax++;
                            if(currentMax > globalMax) {
                                    globalMax = currentMax;
                            }
                    } else {
                            currentMax = 0;
                    }
            }
    }

    // Diagonal
    for(int i = 0; i < rows; i++) {
            for(int j = 0; j < cols; j++) {
                    if(i == j) {
                            continue;
                    }
                    int currentMax = 0;
                    if(mat[i][j] == 1) {
                            currentMax++;
                            if(currentMax > globalMax) {
                                    globalMax = currentMax;
                            }
                    }
            }
    }

    // Anti-diagonal
    for(int i = rows - 1; i >= 0; i--) {
            for(int j = cols - 1; j >= 0; j--) {
                    if(i == j) {
                            continue;
                    }
                    int currentMax = 0;
                    if(mat[i][j] == 1) {
                            currentMax++;
                            if(currentMax > globalMax) {
                                    globalMax = currentMax;
                            }
                    }
            }
    }

    return globalMax;
}

public static int longestLine(int[][] mat) {
