    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j] = 1;
                if (i > 0) {
                    dp[i][j] = Math.max(dp[i][j], dp[i - 1][j] + 1);
                }
                if (j > 0) {
                    dp[i][j] = Math.max(dp[i][j], dp[i][j - 1] + 1);
                }
                maxLen = Math.max(maxLen, dp[i][j]);
            }
        }
    }

    return maxLen;
}

public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int[][] dp = new int[m][n];
    int maxLength = 0;

    // initialize the first row and column of dp table
    for (int i = 0; i < m; i++) {
        dp[i][0] = mat[i][0];
    }

    for (int j = 0; j < n; j++) {
        dp[0][j] = mat[0][j];
    }

    // fill the dp table with the maximum length of the line
    for (int i = 1; i < m; i++) {
        for (int j = 1; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j] = Math.max(dp[i - 1][j - 1], Math.max(dp[i - 1][j], dp[i][j - 1])) + 1;
            } else {
                dp[i][j] = 0;
            }
        }
    }

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            maxLength = Math.max(maxLength, dp[i][j]);
        }
    }

    return maxLength;
}

public static int longestLine(int[][] mat) {
    int maxLength = 0;
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[i].length; j++) {
            if (mat[i][j] == 1) {
                int length = 1;
                if (i > 0 && mat[i - 1][j] == 1) {
                    length = Math.max(length, 1 + longestLine(mat, i - 1, j));
                }
                if (j > 0 && mat[i][j - 1] == 1) {
                    length = Math.max(length, 1 + longestLine(mat, i, j - 1));
                }
                if (i < mat.length - 1 && mat[i + 1][j] == 1) {
                    length = Math.max(length, 1 + longestLine(mat, i + 1, j));
                }
                if (j < mat[i].length - 1 && mat[i][j + 1] == 1) {
                    length = Math.max(length, 1 + longestLine(mat, i, j + 1));
                }
                maxLength = Math.max(maxLength, length);
            }
        }
    }
    return maxLength;
}

private static int longestLine(int[][] mat, int row, int col) {
    if (row < 0 || col < 0 || row >= mat.length || col >= mat[row].length || mat[row][col] != 1) {
        return 0;
    }
    mat[row][col] = 0;
    return 1 + longestLine(mat, row - 1, col) + longestLine(mat, row + 1, col) + longestLine(mat, row, col - 1) + longestLine(mat, row, col + 1);
}

