        for (int i = 0; i < pairs.length; i++) {
            pairs[i] = A[2 * i] + A[2 * i + 1];
        }

        // Count the number of square pairs
        int count = 0;
        for (int i = 0; i < pairs.length; i++) {
            int pair = pairs[i];
            for (int j = 1; j * j <= pair; j++) {
                if (pair % j == 0 && pair / j <= pairs.length) {
                    count++;
                }
            }
        }

        return count;
    }

