public static int largestRectangleArea(int[] heights) {
    // Create a stack to keep track of the indexes of the heights
    Stack<Integer> stack = new Stack<>();
    int maxArea = 0;

    // Loop through the array and calculate the area of each rectangle
    for (int i = 0; i < heights.length; i++) {
        // If the current element is lower than the top of the stack,
        // we can increment the area of the highest rectangle
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            int height = heights[stack.pop()];
            int width = i - stack.peek() - 1;
            maxArea = Math.max(maxArea, height * width);
        }

        // Add the current element to the stack
        stack.push(i);
    }

    // Calculate the area of the remaining rectangles
    while (!stack.isEmpty()) {
        int height = heights[stack.pop()];
        int width = heights.length - stack.peek() - 1;
        maxArea = Math.max(maxArea, height * width);
    }

    return maxArea;
}

