        int row = 0;
        int col = 0;
        for (int i = 0; i < result.length; i++) {
            result[i] = mat[row][col];
            if (row == n - 1) {
                col++;
            } else if (col == m - 1) {
                row++;
            } else if (row == 0) {
                col++;
            } else {
                row--;
            }
        }
        return result;
    }

