    // Convert the integer to a list of digits
    List<Integer> digits = new ArrayList<>();
    while (n > 0) {
        digits.add(n % 10);
        n /= 10;
    }

    // Sort the list of digits in ascending order
    Collections.sort(digits);

    // Build the smallest possible integer by concatenating the sorted digits
    int smallestInteger = 0;
    for (int digit : digits) {
        smallestInteger = smallestInteger * 10 + digit;
    }

    // If the smallest possible integer is greater than the input integer, return -1
    if (smallestInteger > n) {
        return -1;
    }

    return smallestInteger;
}

