public static boolean isBoomerang(int[][] points) {
    // Check if the array contains at least 3 points
    if (points.length < 3) {
        return false;
    }

    // Check if the first and last points are the same
    if (Arrays.equals(points[0], points[points.length - 1])) {
        return false;
    }

    // Check if the slope of the first and last points is the same
    double slope1 = (double) (points[0][1] - points[1][1]) / (double) (points[0][0] - points[1][0]);
    double slope2 = (double) (points[points.length - 1][1] - points[points.length - 2][1]) /
            (double) (points[points.length - 1][0] - points[points.length - 2][0]);
    if (slope1 == slope2) {
        return false;
    }

    // Check if the points form a straight line
    for (int i = 1; i < points.length - 1; i++) {
        double slope = (double) (points[i][1] - points[i + 1][1]) / (double) (points[i][0] - points[i + 1][0]);
        if (slope != slope1 && slope != slope2) {
            return false;
        }
    }

    return true;
}

