public static int minPerfectSquareSum(int n) {
    // base case
    if (n <= 0) {
        return 0;
    }

    // list of perfect square numbers less than or equal to n
    List<Integer> perfectSquares = getPerfectSquares(n);

    // initialize the minimum number of perfect square numbers to n
    int minCount = n;

    // loop through the perfect square numbers and calculate the minimum number of perfect square numbers that sum up to n
    for (int i = 0; i < perfectSquares.size(); i++) {
        int count = 1;
        int remaining = n - perfectSquares.get(i);
        while (remaining > 0) {
            count++;
            remaining -= perfectSquares.get(i);
        }
        minCount = Math.min(minCount, count);
    }

    return minCount;
}

